describe('Numeric Column Summary Row', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should display summary row with total for numeric column', () => {
    // Intercept API call to load table data
    cy.intercept('GET', '/api/table-data').as('loadTableData');
    cy.wait('@loadTableData');

    // Verify summary row is visible
    cy.get('[data-testid="summary-row"]').should('be.visible');

    // Verify summary row contains correct total
    cy.get('[data-testid="summary-row"]').should('contain', 'Total');
    cy.get('[data-testid="summary-row"]').should('contain', '1234');

    // Verify summary row has correct formatting
    cy.get('[data-testid="summary-row"]').should('have.css', 'text-align', 'right');
    cy.get('[data-testid="summary-row"]').should('have.css', 'font-weight', 'bold');

    // Verify summary row is styled differently from other rows
    cy.get('[data-testid="table-row"]').should('not.have.css', 'background-color');
    cy.get('[data-testid="summary-row"]').should('have.css', 'background-color', 'lightgrey');
  });

  it('should hide summary row when numeric column is empty', () => {
    // Intercept API call to load table data with empty numeric column
    cy.intercept('GET', '/api/table-data').as('loadTableDataEmpty');
    cy.wait('@loadTableDataEmpty');

    // Verify summary row is initially visible
    cy.get('[data-testid="summary-row"]').should('be.visible');

    // Verify summary row shows "No data" message
    cy.get('[data-testid="summary-row"]').should('contain', 'No data');

    // Verify summary row is still styled differently
    cy.get('[data-testid="summary-row"]').should('have.css', 'background-color', 'lightgrey');

    // Verify summary row is still visible when numeric column is empty
    cy.get('[data-testid="summary-row"]').should('be.visible');
  });
});
